// ==========================================================================
// MCP AGENT NODE - Identify Tool Intent & Prepare Payload
// ==========================================================================
const body = $input.first()?.json?.body || $input.first()?.json || {};

let tool = body.tool || body.action || 'auto';
const query = body.query || body.search || '';
const url = body.url || body.link || '';
const filename = body.filename || body.file_name || '';
const file_base64 = body.file_base64 || body.base64 || '';
const chart_type = body.chart_type || body.type || 'soil_npk';
const chart_format = body.format || 'echarts';

// Auto-detect tool if not explicitly specified
if (tool === 'auto') {
  if (body.chart_type || body.chart_data || body.is_chart) {
    tool = 'visualize_chart';
  } else if (file_base64 || filename || body.file_path) {
    tool = 'parse_document';
  } else if (url && !query) {
    tool = 'scrape';
  } else if (body.full_research || body.research) {
    tool = 'research';
  } else {
    tool = 'search';
  }
}

return [{
  json: {
    tool: tool,
    query: query,
    url: url,
    filename: filename,
    file_base64: file_base64,
    file_path: body.file_path || '',
    file_type: body.file_type || '',
    chart_type: chart_type,
    chart_format: chart_format,
    chart_payload: body.chart_payload || body.data || body,
    language: body.language || 'id',
    generate_pdf: body.generate_pdf !== false,
    max_results: parseInt(body.max_results || 8),
    request_id: `mcp_${Date.now()}`,
    timestamp: new Date().toISOString()
  }
}];

// ==========================================================================
// CHART VISUALIZATION ENGINE (Plotly / Apache ECharts Standard)
// ==========================================================================
const input = $input.first().json;
const chartType = (input.chart_type || 'soil_npk').toLowerCase();
const format = (input.chart_format || 'echarts').toLowerCase();
const payload = input.chart_payload || {};

let chartSpec = {};

if (chartType.includes('soil') || chartType.includes('npk') || chartType.includes('radar')) {
  const n = Number(payload.n || payload.nitrogen || 90);
  const p = Number(payload.p || payload.phosphorus || 40);
  const k = Number(payload.k || payload.potassium || 50);
  const ph = Number(payload.ph || 6.5);
  const moisture = Number(payload.moisture || 70);

  if (format === 'plotly') {
    chartSpec = {
      format: 'plotly',
      chart_type: 'radar',
      data: [{
        type: 'scatterpolar',
        r: [n, p, k, ph * 10, moisture, n],
        theta: ['Nitrogen', 'Fosfor', 'Kalium', 'pH x10', 'Kelembaban', 'Nitrogen'],
        fill: 'toself',
        line: { color: '#16a34a' }
      }],
      layout: { title: 'Profil Kesuburan Tanah (NPK)' }
    };
  } else {
    chartSpec = {
      format: 'echarts',
      chart_type: 'radar',
      option: {
        title: { text: 'Profil Kesuburan Tanah (NPK)', left: 'center' },
        tooltip: { trigger: 'item' },
        radar: {
          indicator: [
            { name: `Nitrogen (${n})`, max: 140 },
            { name: `Fosfor (${p})`, max: 80 },
            { name: `Kalium (${k})`, max: 150 },
            { name: `pH (${ph})`, max: 14 },
            { name: `Kelembaban (${moisture}%)`, max: 100 }
          ]
        },
        series: [{
          type: 'radar',
          data: [{ value: [n, p, k, ph, moisture], name: 'Status Aktual Lahan' }],
          areaStyle: { color: 'rgba(22, 163, 74, 0.4)' },
          lineStyle: { color: '#16a34a' }
        }]
      }
    };
  }
} else {
  chartSpec = {
    format: format,
    chart_type: chartType,
    option: {
      title: { text: 'AgriSensa Visualisasi', left: 'center' },
      series: []
    }
  };
}

return [{
  json: {
    success: true,
    chart_type: chartType,
    format: format,
    spec: chartSpec
  }
}];

// Merge and format output
const result = $input.first().json;
const agentInfo = $('MCP Intent Agent').item.json;

return [{
  json: {
    success: result.success !== false,
    tool_used: agentInfo.tool,
    request_id: agentInfo.request_id,
    output: result.data || result.spec || result,
    timestamp: new Date().toISOString()
  }
}];
